import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import {
  Mail,
  Lock,
  Eye,
  EyeOff,
  User,
  Phone,
  Building2,
  FileCheck,
  MapPin,
  ShoppingBag,
  Store,
  CheckCircle2,
  ShieldCheck,
  Truck,
  Headphones,
  Users,
} from "lucide-react";
import { useAuth } from "../context/AuthContext";

const API = "/api";

const validateEmail = (email) => {
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return re.test(email);
};

const validateLocation = (location) => {
  return location && location.trim().length >= 3 && /[a-zA-Z]/.test(location);
};

const validateGST = (gst) => {
  const gstRegex = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;
  return gstRegex.test(gst.toUpperCase());
};

const ROLES = [
  {
    id: "customer",
    label: "Customer",
    icon: ShoppingBag,
    desc: "Buy power tools & track orders",
    color: "#dc2626",
    bg: "#fef2f2",
  },
  {
    id: "dealer",
    label: "Shopkeeper / Dealer",
    icon: Store,
    desc: "Retail shop registration",
    color: "#111827",
    bg: "#f8fafc",
  },
];

const InputField = ({ label, icon: Icon, error, ...props }) => (
  <div>
    <label
      style={{
        fontSize: "12px",
        fontWeight: 600,
        marginBottom: "6px",
        display: "block",
        color: "#475569",
      }}
    >
      {label}
    </label>
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: "10px",
        border: `1px solid ${error ? "#fecaca" : "#e2e8f0"}`,
        borderRadius: "14px",
        padding: "12px 14px",
        background: "#ffffff",
      }}
    >
      {Icon && <Icon size={16} color={error ? "#dc2626" : "#94a3b8"} />}
      <input
        {...props}
        style={{
          flex: 1,
          border: "none",
          outline: "none",
          fontSize: "14px",
          background: "transparent",
          color: "#0f172a",
        }}
      />
    </div>
    {error && (
      <p
        style={{
          color: "#dc2626",
          fontSize: "11px",
          marginTop: "6px",
          fontWeight: 500,
        }}
      >
        ⚠ {error}
      </p>
    )}
  </div>
);

const Register = () => {
  const navigate = useNavigate();
  const { login } = useAuth();
  const [selectedRole, setSelectedRole] = useState("customer");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [serverError, setServerError] = useState("");
  const [form, setForm] = useState({
    name: "",
    phone: "",
    email: "",
    password: "",
    confirmPassword: "",
    companyName: "",
    gstNumber: "",
    location: "",
  });
  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({
      ...prev,
      [name]: name === "gstNumber" ? value.toUpperCase() : value,
    }));
    if (errors[name]) setErrors((prev) => ({ ...prev, [name]: "" }));
  };

  const validate = () => {
    const errs = {};
    if (!form.name.trim()) errs.name = "Full name is required";
    if (
      !form.phone.trim() ||
      !/^[6-9]\d{9}$/.test(form.phone.replace(/\s/g, ""))
    )
      errs.phone = "Enter a valid 10-digit mobile number";
    if (!validateEmail(form.email))
      errs.email = "Enter a valid email address (e.g. user@gmail.com)";
    if (form.password.length < 6)
      errs.password = "Password must be at least 6 characters";
    if (form.password !== form.confirmPassword)
      errs.confirmPassword = "Passwords do not match";
    if (selectedRole === "dealer") {
      if (!form.companyName.trim())
        errs.companyName = "Company name is required";
      if (!form.gstNumber.trim()) errs.gstNumber = "GST number is required";
      if (form.gstNumber && !validateGST(form.gstNumber))
        errs.gstNumber = "Invalid GST number format";
      if (!validateLocation(form.location))
        errs.location = "Enter a valid city and state";
    }
    return errs;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationErrors = validate();
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }
    setServerError("");
    setLoading(true);
    try {
      const endpoint =
        selectedRole === "customer"
          ? `${API}/auth/register`
          : `${API}/auth/dealer/register`;
      const body = {
        name: form.name,
        phone: form.phone,
        email: form.email,
        password: form.password,
        ...(selectedRole === "dealer"
          ? {
              companyName: form.companyName,
              gstNumber: form.gstNumber,
              location: form.location,
            }
          : {}),
      };
      const response = await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "Registration failed");
      const userData = data.customer || data.user || {};
      login({
        ...userData,
        userType: selectedRole,
        token: data.token,
        loginTime: new Date().toISOString(),
      });
      setSuccess(true);
      setTimeout(() => {
        navigate(
          selectedRole === "customer"
            ? "/customer-dashboard"
            : "/dealer-dashboard",
        );
      }, 1800);
    } catch (error) {
      setServerError(error.message);
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div
        style={{
          minHeight: "100vh",
          background: "linear-gradient(135deg, #0f172a 0%, #1e293b 100%)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "40px 20px",
        }}
      >
        <div style={{ textAlign: "center", color: "#fff" }}>
          <div
            style={{
              width: "88px",
              height: "88px",
              borderRadius: "50%",
              background: "linear-gradient(135deg, #10b981, #059669)",
              display: "grid",
              placeItems: "center",
              margin: "0 auto 22px",
            }}
          >
            <CheckCircle2 size={40} color="#fff" />
          </div>
          <h2
            style={{
              fontSize: "32px",
              margin: 0,
              fontWeight: 900,
              color: "#fff",
            }}
          >
            Registration successful
          </h2>
          <p
            style={{
              marginTop: "14px",
              color: "#cbd5e1",
              fontSize: "16px",
              lineHeight: 1.7,
            }}
          >
            आपका {selectedRole === "customer" ? "Customer" : "Dealer"} account
            बन गया है। अब आपको आपके dashboard पर भेजा जा रहा है।
          </p>
        </div>
      </div>
    );
  }

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "#f8fafc",
        padding: "32px 20px 60px",
      }}
    >
      <div
        style={{
          maxWidth: "1240px",
          margin: "0 auto",
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))",
          gap: "24px",
          alignItems: "start",
        }}
      >
        <section
          style={{
            background: "#ffffff",
            borderRadius: "32px",
            boxShadow: "0 40px 90px rgba(15,23,42,0.08)",
            overflow: "hidden",
            display: "flex",
            flexDirection: "column",
          }}
        >
          <div style={{ padding: "34px 34px 24px" }}>
            <p
              style={{
                margin: 0,
                color: "#dc2626",
                fontWeight: 700,
                letterSpacing: "0.12em",
                fontSize: "12px",
                textTransform: "uppercase",
              }}
            >
              Dushyant Power Tools
            </p>
            <h1
              style={{
                margin: "18px 0 0",
                fontSize: "3rem",
                fontWeight: 900,
                lineHeight: 1,
                color: "#0f172a",
              }}
            >
              Join Our Growing Family
            </h1>
            <p
              style={{
                marginTop: "18px",
                color: "#475569",
                fontSize: "1rem",
                lineHeight: 1.8,
                maxWidth: "560px",
              }}
            >
              Whether you’re a customer, dealer, or shopkeeper — we have the
              perfect platform for you.
            </p>
          </div>
          <div style={{ padding: "0 34px 34px" }}>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
                gap: "16px",
                marginBottom: "24px",
              }}
            >
              {[
                {
                  icon: ShieldCheck,
                  title: "100% Genuine Products",
                  subtitle: "Original Quality Guaranteed",
                },
                {
                  icon: Users,
                  title: "Best Dealer Support",
                  subtitle: "Dedicated help always",
                },
                {
                  icon: Truck,
                  title: "Fast & Reliable Delivery",
                  subtitle: "Pan India Express",
                },
                {
                  icon: Headphones,
                  title: "Dedicated Assistance",
                  subtitle: "24x7 Customer Support",
                },
              ].map((item) => (
                <div
                  key={item.title}
                  style={{
                    background: "#f8fafc",
                    borderRadius: "22px",
                    padding: "18px",
                    border: "1px solid #e2e8f0",
                    display: "flex",
                    gap: "12px",
                    alignItems: "flex-start",
                  }}
                >
                  <div
                    style={{
                      width: "40px",
                      height: "40px",
                      borderRadius: "14px",
                      background: "#ffffff",
                      display: "grid",
                      placeItems: "center",
                      color: "#dc2626",
                      border: "1px solid #fde8e8",
                    }}
                  >
                    <item.icon size={18} />
                  </div>
                  <div>
                    <p
                      style={{
                        margin: 0,
                        fontSize: "14px",
                        fontWeight: 700,
                        color: "#0f172a",
                      }}
                    >
                      {item.title}
                    </p>
                    <p
                      style={{
                        margin: "8px 0 0",
                        fontSize: "12px",
                        color: "#64748b",
                      }}
                    >
                      {item.subtitle}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>
          <div style={{ minHeight: "290px", background: "#f8fafc" }}>
            <img
              src="data:image/jpeg;base64,"
              alt="Dushyant Power Tools"
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                display: "block",
              }}
            />
          </div>
          <div style={{ padding: "28px 34px 34px" }}>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
                gap: "14px",
              }}
            >
              {[
                { value: "5000+", label: "Happy Customers" },
                { value: "50+", label: "Cities Covered" },
                { value: "1000+", label: "Quality Products" },
                { value: "24x7", label: "Support" },
              ].map((item) => (
                <div
                  key={item.label}
                  style={{
                    textAlign: "center",
                    borderRadius: "20px",
                    background: "#fff",
                    padding: "16px",
                    border: "1px solid #e2e8f0",
                  }}
                >
                  <p
                    style={{
                      margin: 0,
                      fontSize: "18px",
                      fontWeight: 800,
                      color: "#0f172a",
                    }}
                  >
                    {item.value}
                  </p>
                  <p
                    style={{
                      margin: "8px 0 0",
                      fontSize: "12px",
                      color: "#64748b",
                    }}
                  >
                    {item.label}
                  </p>
                </div>
              ))}
            </div>
          </div>
        </section>

        <section
          style={{
            upper: "10%",
            height: "100%",
            background: "#ffffff",
            borderRadius: "32px",
            boxShadow: "0 40px 90px rgba(15,23,42,0.08)",
            overflow: "hidden",
          }}
        >
          <div style={{ padding: "90px 34px 24px" }}>
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: "12px",
                marginBottom: "24px",
              }}
            >
              <div
                style={{
                  width: "422px",
                  height: "462px",
                  borderRadius: "24px",
                  background: "white",
                  display: "grid",
                  placeItems: "center",
                }}
              >
                <img
                  src="http://localhost:5173/images/login-storefront.jpeg"
                  alt="DPT Logo"
                  style={{
                    width: "420px",
                    height: "460px",
                    objectFit: "contain",
                    borderRadius: "30px",
                  }}
                />
              </div>
              <div style={{ textAlign: "center" }}>
                <p
                  style={{
                    margin: 0,
                    fontSize: "12px",
                    fontWeight: 700,
                    color: "#dc2626",
                    letterSpacing: "0.14em",
                  }}
                >
                  DUSHYANT POWER TOOLS
                </p>
                <h2
                  style={{
                    margin: "8px 0 0",
                    fontSize: "30px",
                    fontWeight: 900,
                    color: "#0f172a",
                  }}
                >
                  Create Your Account
                </h2>
                <p
                  style={{
                    marginTop: "10px",
                    color: "#64748b",
                    fontSize: "14px",
                    lineHeight: 1.7,
                  }}
                >
                  Register to access your profile, orders, and pricing.
                </p>
              </div>
            </div>

            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: "12px",
                marginBottom: "22px",
              }}
            >
              {ROLES.map((role) => {
                const isActive = selectedRole === role.id;
                return (
                  <button
                    key={role.id}
                    type="button"
                    onClick={() => {
                      setSelectedRole(role.id);
                      setErrors({});
                      setServerError("");
                    }}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "12px",
                      padding: "16px 18px",
                      borderRadius: "18px",
                      border: `1px solid ${isActive ? "#dc2626" : "#e2e8f0"}`,
                      background: isActive ? "rgba(220,38,38,0.08)" : "#ffffff",
                      cursor: "pointer",
                      color: isActive ? "#dc2626" : "#475569",
                      fontWeight: 700,
                      textAlign: "left",
                    }}
                  >
                    <div
                      style={{
                        width: "36px",
                        height: "36px",
                        borderRadius: "14px",
                        background: isActive ? "#fee2e2" : "#f8fafc",
                        display: "grid",
                        placeItems: "center",
                      }}
                    >
                      <role.icon
                        size={18}
                        color={isActive ? "#dc2626" : "#9ca3af"}
                      />
                    </div>
                    <div>
                      <div style={{ fontSize: "13px" }}>{role.label}</div>
                      <div
                        style={{
                          marginTop: "4px",
                          fontSize: "11px",
                          color: "#667085",
                        }}
                      >
                        {role.desc}
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>

            {serverError && (
              <div
                style={{
                  padding: "14px 16px",
                  borderRadius: "16px",
                  background: "#fee2e2",
                  border: "1px solid #fecaca",
                  color: "#b91c1c",
                  marginBottom: "20px",
                }}
              >
                {serverError}
              </div>
            )}

            <form
              onSubmit={handleSubmit}
              style={{ display: "grid", gap: "16px" }}
            >
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: "16px",
                }}
              >
                <InputField
                  label="Full Name *"
                  icon={User}
                  name="name"
                  value={form.name}
                  onChange={handleChange}
                  placeholder="Your Name"
                  required
                  error={errors.name}
                />
                <InputField
                  label="Mobile Number *"
                  icon={Phone}
                  name="phone"
                  value={form.phone}
                  onChange={handleChange}
                  placeholder="9876543210"
                  type="tel"
                  required
                  error={errors.phone}
                />
              </div>

              <InputField
                label="Email Address *"
                icon={Mail}
                name="email"
                value={form.email}
                onChange={handleChange}
                placeholder="you@example.com"
                type="email"
                required
                error={errors.email}
              />

              {selectedRole === "dealer" && (
                <>
                  <div
                    style={{
                      display: "grid",
                      gridTemplateColumns: "1fr 1fr",
                      gap: "16px",
                    }}
                  >
                    <InputField
                      label="Company / Shop Name *"
                      icon={Building2}
                      name="companyName"
                      value={form.companyName}
                      onChange={handleChange}
                      placeholder="Company or Shop"
                      required
                      error={errors.companyName}
                    />
                    <InputField
                      label="GST Number *"
                      icon={FileCheck}
                      name="gstNumber"
                      value={form.gstNumber}
                      onChange={handleChange}
                      placeholder="22AAAAA0000A1Z5"
                      required
                      error={errors.gstNumber}
                    />
                  </div>
                  <InputField
                    label="Business Location *"
                    icon={MapPin}
                    name="location"
                    value={form.location}
                    onChange={handleChange}
                    placeholder="Sidhi, Madhya Pradesh"
                    required
                    error={errors.location}
                  />
                </>
              )}

              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: "16px",
                }}
              >
                <div>
                  <label
                    style={{
                      display: "block",
                      marginBottom: "6px",
                      fontSize: "12px",
                      fontWeight: 600,
                      color: "#475569",
                    }}
                  >
                    Password *
                  </label>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "10px",
                      border: `1px solid ${errors.password ? "#fecaca" : "#e2e8f0"}`,
                      borderRadius: "14px",
                      padding: "12px 14px",
                      background: "#ffffff",
                    }}
                  >
                    <Lock size={16} color="#94a3b8" />
                    <input
                      type={showPassword ? "text" : "password"}
                      name="password"
                      value={form.password}
                      onChange={handleChange}
                      placeholder="Enter password"
                      style={{
                        flex: 1,
                        border: "none",
                        outline: "none",
                        fontSize: "14px",
                        background: "transparent",
                        color: "#0f172a",
                      }}
                      required
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      style={{
                        border: "none",
                        background: "none",
                        cursor: "pointer",
                        color: "#9ca3af",
                      }}
                    >
                      {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  </div>
                  {errors.password && (
                    <p
                      style={{
                        color: "#dc2626",
                        fontSize: "11px",
                        marginTop: "6px",
                      }}
                    >
                      ⚠ {errors.password}
                    </p>
                  )}
                </div>
                <div>
                  <label
                    style={{
                      display: "block",
                      marginBottom: "6px",
                      fontSize: "12px",
                      fontWeight: 600,
                      color: "#475569",
                    }}
                  >
                    Confirm Password *
                  </label>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "10px",
                      border: `1px solid ${errors.confirmPassword ? "#fecaca" : "#e2e8f0"}`,
                      borderRadius: "14px",
                      padding: "12px 14px",
                      background: "#ffffff",
                    }}
                  >
                    <Lock size={16} color="#94a3b8" />
                    <input
                      type={showPassword ? "text" : "password"}
                      name="confirmPassword"
                      value={form.confirmPassword}
                      onChange={handleChange}
                      placeholder="Confirm password"
                      style={{
                        flex: 1,
                        border: "none",
                        outline: "none",
                        fontSize: "14px",
                        background: "transparent",
                        color: "#0f172a",
                      }}
                      required
                    />
                  </div>
                  {errors.confirmPassword && (
                    <p
                      style={{
                        color: "#dc2626",
                        fontSize: "11px",
                        marginTop: "6px",
                      }}
                    >
                      ⚠ {errors.confirmPassword}
                    </p>
                  )}
                </div>
              </div>

              <button
                type="submit"
                disabled={loading}
                style={{
                  width: "100%",
                  padding: "16px",
                  borderRadius: "16px",
                  border: "none",
                  background: loading
                    ? "#94a3b8"
                    : "linear-gradient(135deg, #dc2626 0%, #991b1b 100%)",
                  color: "#ffffff",
                  fontSize: "15px",
                  fontWeight: 700,
                  cursor: loading ? "not-allowed" : "pointer",
                }}
              >
                {loading
                  ? "Registering..."
                  : `Register as ${selectedRole === "customer" ? "Customer" : "Dealer"}`}
              </button>
            </form>

            <p
              style={{
                marginTop: "22px",
                textAlign: "center",
                color: "#64748b",
                fontSize: "13px",
              }}
            >
              Already have an account?{" "}
              <Link
                to="/login"
                style={{
                  color: "#dc2626",
                  fontWeight: 700,
                  textDecoration: "none",
                }}
              >
                Login here
              </Link>
            </p>
          </div>
        </section>
      </div>
    </div>
  );
};

export default Register;
